// intake.conditions.expire — E2 AC3, SOP-DEL-01 §8. Generated by `pnpm gen:command`; guard cases kept,
// acceptance cases added. The condition comes from the real intake commands.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import {
  aStaffActor,
  countRows,
  createFakeClock,
  createTestDatabase,
  runAsOwner,
  type TestDatabase,
} from '@ocs/testing';
import { Forbidden, grantOf, openTestKernel, systemActor, type TestKernel } from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { decideIntake } from '../commands/decide-intake.ts';
import { expireConditions } from '../commands/expire-conditions.ts';
import { saveHandoverCard } from '../commands/save-handover-card.ts';
import { submitHandoverCard } from '../commands/submit-handover-card.ts';
import { itemCodes } from '../rules/handover-checklist.ts';

const job = systemActor('intake-conditions');
const sales = aStaffActor({ roles: ['sales'] });
const director = aStaffActor({ roles: ['director'] });
const clock = createFakeClock(new Date('2026-11-20T09:00:00Z'));
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
const expire = () => t.kernel.execute(expireConditions, job, {}, 'system');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  t.grant(director, createClient.permission, createSite.permission, decideIntake.permission);
  t.grant(sales, saveHandoverCard.permission, submitHandoverCard.permission);
  t.grant(job, expireConditions.permission);
  const a = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTA', name: 'Client A' },
    'test',
  );
  const place = { countryCode: 'GB', cityCode: 'LON', cityName: 'London', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, director, { clientId: a.id, ...place }, 'test'));
  const items = itemCodes.map((code) =>
    code.startsWith('F')
      ? { code, status: 'provided' }
      : { code, status: 'provided', value: 'in the folder' },
  );
  const content = { identification: { projectName: 'Counting', projectType: 'new', salesOwnerId: sales.id } };
  const card = { siteId: siteA, content, items, installsOrConfigures: true, newClientOrPlace: true };
  await t.kernel.execute(saveHandoverCard, sales, card, 'test');
  await t.kernel.execute(submitHandoverCard, sales, { siteId: siteA }, 'test');
  const condition = { itemCode: 'B2', text: 'secondary contact', deadline: '2026-11-24' };
  const decision = {
    siteId: siteA,
    decision: 'accepted_with_conditions',
    folderStandard: 'L',
    conditions: [condition],
  };
  await t.kernel.execute(decideIntake, director, decision, 'test');
  await runAsOwner(
    testDb.url,
    `INSERT INTO auth."user" (id, name, email, kind) VALUES ($1, 'Person 01', 'director@example.com', 'staff')`,
    [director.id],
  );
  await runAsOwner(
    testDb.url,
    `INSERT INTO auth.user_role (id, user_id, role, granted_by) VALUES (gen_random_uuid(), $1, 'director', $1)`,
    [director.id],
  );
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('intake.conditions.expire', () => {
  it('is for the system only', async () => {
    expect(grantOf(expireConditions.permission)?.roles).toEqual(['system']);
    await expect(t.kernel.execute(expireConditions, director, {}, 'test')).rejects.toBeInstanceOf(Forbidden);
  });

  it('nothing expires on or before the deadline', async () => {
    clock.advance({ hours: 24 * 4 }); // Tue 24 Nov, the deadline itself
    expect((await expire()).expired).toEqual([]);
  });

  it('after the deadline the condition expires once, naming the Sales owner and the director to alert', async () => {
    clock.advance({ hours: 24 });
    const r = await expire();
    expect(r.expired.map((e) => [e.itemCode, e.deadline, [...e.notify].sort()])).toEqual([
      ['B2', '2026-11-24', [sales.id, director.id].sort()],
    ]);
    expect(await countRows(testDb.url, `intake_condition WHERE status = 'expired'`, [])).toBe(1);
    expect((await expire()).expired).toEqual([]);
  });
});
